先运行此动作，然后激活想要无视win+d的窗口，按ctrl+shift+L即可实现置顶，再次按即可取消置顶"}},"OutputParams":{},"IfSteps":null,"ElseSteps":null,"Note":"","Disabled":false,"Collapsed":false,"DelayMs":0},{"StepRunnerKey":"sys:runScript","InputParams":{"script":{"VarKey":null,"Value":"#Requires AutoHotkey v2.0
#SingleInstance Force

ShowTip(message) {
    ToolTip message
    SetTimer () => ToolTip(), -1200
}

^+l:: {
    hwnd := WinExist("A")
    if !hwnd {
        SoundBeep 750, 120
        ShowTip("No active window found.")
        return
    }

    processName := WinGetProcessName("ahk_id " hwnd)
    if processName {
        processName := RegExReplace(processName, "\.exe$")
    } else {
        processName := "Window"
    }

    exStyle := WinGetExStyle("ahk_id " hwnd)
    isToolWindow := (exStyle & 0x80) != 0
    isAlwaysOnTop := (exStyle & 0x8) != 0

    if isToolWindow || isAlwaysOnTop {
        WinSetAlwaysOnTop 0, "ahk_id " hwnd
        WinSetExStyle "^0x80", "ahk_id " hwnd
        SoundBeep 500, 120
        ShowTip(processName " unpinned")
    } else {
        WinSetAlwaysOnTop 1, "ahk_id " hwnd
        WinSetExStyle "^0x80", "ahk_id " hwnd
        SoundBeep 900, 120
        ShowTip(processName " pinned")
    }
}
